function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function slugify(s){ return String(s||'').toLowerCase().replace(/[^a-z0-9一-鿿]+/g,'-').replace(/^-+|-+$/g,'').slice(0,40)||'my-skill'; }
function buildSkillSpec(o){
  o=o||{};
  var name=String(o.name||'').trim()||'My Skill';
  var desc=String(o.desc||'').trim()||'（待填写：这个 skill 做什么、何时用）';
  var trigger=String(o.trigger||'').trim()||'（待填写：什么情况下应触发此 skill）';
  var steps=splitLines(o.steps); if(!steps.length) steps=['（待补充执行步骤）'];
  var constraints=splitLines(o.constraints); if(!constraints.length) constraints=['仅处理用户明确授权的内容','不执行破坏性操作，除非用户确认'];
  var notes=splitLines(o.notes);
  var slug=slugify(name);
  var lines=[];
  lines.push('---');
  lines.push('name: '+slug);
  lines.push('description: '+desc);
  lines.push('---');
  lines.push('');
  lines.push('# '+name);
  lines.push('');
  lines.push('## 概述');
  lines.push(desc);
  lines.push('');
  lines.push('## 触发条件（何时使用）');
  lines.push(trigger);
  lines.push('');
  lines.push('## 步骤');
  steps.forEach(function(s,i){ lines.push((i+1)+'. '+s); });
  lines.push('');
  lines.push('## 安全与约束');
  constraints.forEach(function(c){ lines.push('- '+c); });
  if(notes.length){ lines.push(''); lines.push('## 注意事项'); notes.forEach(function(n){ lines.push('- '+n); }); }
  return {title:name+' skill 规格', slug:slug, stepCount:steps.length, constraintCount:constraints.length, hasTrigger:trigger.indexOf('（待填写')<0, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, slugify:slugify, buildSkillSpec:buildSkillSpec};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SkillSpecForgePure = EXPORTS; }
